using System.Collections;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using CatGunner.Runtime;

public sealed class BulletTests
{
    private static CurrencyAmount Amount(int n) => CurrencyAmount.FromValue(new DecimalAmount(n));
    private static IEnumerator Load()
    {
        yield return SceneManager.LoadSceneAsync("Forest");yield return null;
        Cat.instance.GetComponent<ForestCombatAcceptance>().enabled=false;
        Assert.That(Polling_manager.instance,Is.Not.Null);
    }
    [UnityTest]
    public IEnumerator OriginalPoolPreservesReferencesAndDoesNotStealLiveProjectiles()
    {
        yield return Load();var manager=Polling_manager.instance;var pool=manager.Polling_List[0];
        Assert.That(pool.Objects.Length,Is.EqualTo(27));Assert.That(manager.Polling_List[1].Objects.Length,Is.EqualTo(10));
        foreach(var go in pool.Objects)
        {
            var bullet=go.GetComponent<Bullet>();
            Assert.That(bullet.rb,Is.Not.Null);Assert.That(bullet.particle,Is.Not.Null);
            Assert.That(bullet.Speed,Is.EqualTo(70));Assert.That(bullet.Skin_particles.Length,Is.EqualTo(65));
            Assert.That(bullet.Skin_particles.All(p=>p!=null),Is.True);
            Assert.That(go.GetComponentsInChildren<BounceStart>(true).Length,Is.EqualTo(1),"Original Bounce_Stat child, not root");
            go.SetActive(false);
        }
        manager.Polling_List[0].Object_Count=0;
        Assert.That(manager.Object_Polling_Smart(0),Is.SameAs(pool.Objects[0]));
        pool.Objects[0].SetActive(true);
        Assert.That(manager.Object_Polling_Smart(0),Is.SameAs(pool.Objects[1]));
        foreach(var go in pool.Objects) {go.GetComponent<Bullet>().is_Die=false;go.SetActive(true);}
        int cursor=manager.Polling_List[0].Object_Count;
        Assert.That(manager.Object_Polling_Smart(0),Is.Null);
        var cat=Cat.instance;cat.GunNum=0;
        Assert.That(cat.TrySpawnBulletEx(Vector3.one*1000,Vector3.forward,GunType.SINGLE,0,1,Amount(100),"100",false),Is.False);
        Assert.That(manager.Polling_List[0].Object_Count,Is.EqualTo(cursor));
        var dead=pool.Objects[3].GetComponent<Bullet>();dead.DieAndWait();
        Assert.That(dead.IsInvoking("Deactivate"),Is.True);
        Assert.That(manager.Object_Polling_Smart(0),Is.SameAs(pool.Objects[3]));
        Assert.That(pool.Objects[3].activeSelf,Is.False);Assert.That(dead.IsInvoking("Deactivate"),Is.False);
        manager.Polling_List[0].Object_Count=3;
        Assert.That(cat.TrySpawnBulletEx(new Vector3(1000,0,1000),Vector3.forward,GunType.SINGLE,0,5,Amount(123),"123",true),Is.True);
        Assert.That(dead.is_Die,Is.False);Assert.That(dead.rb.isKinematic,Is.False);
        Assert.That(dead.GetComponent<Collider>().enabled,Is.True);Assert.That(dead.IsInvoking("Destroy"),Is.True);
        Assert.That(dead.Damage.Value.CompareTo(new DecimalAmount(123)),Is.Zero);
    }

    [UnityTest]
    public IEnumerator RealOriginalProjectileCollisionDamagesTreePlaysFXAndRecycles()
    {
        yield return Load();var manager=Polling_manager.instance;var cat=Cat.instance;cat.GunNum=0;
        var tree=Object.FindObjectsByType<Tree>(FindObjectsInactive.Exclude).First(t=>t!=Tree_manager.instance.Boss_tree);
        foreach(var other in Object.FindObjectsByType<Tree>(FindObjectsInactive.Exclude)) if(other!=tree) other.gameObject.SetActive(false);
        tree.enemy.Spawn(Amount(250),Amount(20));
        var collider=tree.GetComponentsInChildren<Collider>().Single(c=>c.GetComponent<EnemyColl>()!=null);
        var center=collider.bounds.center;var start=center-Vector3.forward*12;
        int texts=0;bool criticalSeen=false;
        System.Action<Vector3,string,bool> text=(point,value,critical)=>{texts++;criticalSeen=critical;Assert.That(value,Is.EqualTo("100"));};
        ForestDamageDispatch.DamageTextPending+=text;
        try
        {
            Assert.That(cat.TrySpawnBulletEx(start,Vector3.forward,GunType.SINGLE,0,5,Amount(100),"100",true),Is.True);
            var bullet=manager.Polling_List[0].Objects.First(go=>go.activeInHierarchy).GetComponent<Bullet>();
            Assert.That(bullet.rb.linearVelocity.z,Is.EqualTo(70).Within(.01));
            for(int i=0;i<50 && !bullet.is_Die;i++) yield return new WaitForFixedUpdate();
            Assert.That(bullet.is_Die,Is.True,"Must reach tree through real physics trigger, not SendMessage");
            Assert.That(tree.enemy.Health_Now.Value.CompareTo(new DecimalAmount(150)),Is.Zero);
            Assert.That(texts,Is.EqualTo(1));Assert.That(criticalSeen,Is.True);
            Assert.That(tree.enemy.Slider.gameObject.activeSelf,Is.True);
            Assert.That(bullet.rb.isKinematic,Is.True);Assert.That(bullet.GetComponent<Collider>().enabled,Is.False);
            Assert.That(manager.Polling_List[1].Objects.Any(go=>go.activeInHierarchy && go.GetComponent<Bullet_FX>().particle.isPlaying),Is.True);
            bullet.SendMessage("OnTriggerEnter",collider);Assert.That(texts,Is.EqualTo(1),"Dead bullet cannot damage twice");
            yield return new WaitForSeconds(1.1f);Assert.That(bullet.gameObject.activeSelf,Is.False);
            int count=Tree_manager.instance.TreeCount_Now;
            // Next original collision is lethal. Reuse original objects, no allocation.
            ForestDamageDispatch.DamageTextPending-=text;
            Assert.That(cat.TrySpawnBulletEx(start,Vector3.forward,GunType.SINGLE,0,5,Amount(150),"150",false),Is.True);
            for(int i=0;i<50 && tree.gameObject.activeSelf;i++) yield return new WaitForFixedUpdate();
            Assert.That(tree.gameObject.activeSelf,Is.False);
            Assert.That(Tree_manager.instance.TreeCount_Now,Is.EqualTo(count-1));
        }
        finally {ForestDamageDispatch.DamageTextPending-=text;}
    }

    [UnityTest]
    public IEnumerator NativeTravelDistanceLimitAndDelayedReturnCancelOldInvokesOnRespawn()
    {
        yield return Load();var manager=Polling_manager.instance;
        var go=manager.Object_Polling_Smart(0);var bullet=go.GetComponent<Bullet>();
        bullet.SpawnEx(0,new Vector3(500,0,500),Vector3.forward,Amount(100),"100",false,GunType.SINGLE,0,640,5);
        var start=bullet.transform.position;
        yield return new WaitForSeconds(.8f);
        Assert.That(bullet.transform.position.z-start.z,Is.InRange(45,57));
        Assert.That(bullet.is_Die,Is.True,"Native lifetime min(requested,50/Max(speed,.1))");
        Assert.That(go.activeSelf,Is.True,"Original 1-second trail/deactivation wait");
        Assert.That(bullet.IsInvoking("Deactivate"),Is.True);
        yield return new WaitForSeconds(1.1f);Assert.That(go.activeSelf,Is.False);
        bullet.SpawnEx(0,new Vector3(500,0,500),Vector3.forward,Amount(100),"100",false,GunType.SHOTGUN,0,640,.1f);
        yield return new WaitForSeconds(.15f);Assert.That(bullet.is_Die,Is.True);
        bullet.SpawnEx(1,new Vector3(600,0,500),Vector3.forward,Amount(200),"200",false,GunType.SINGLE,0,640,.6f);
        Assert.That(bullet.is_Die,Is.False);Assert.That(bullet.IsInvoking("Deactivate"),Is.False);
        Assert.That(bullet.GetComponent<Collider>().enabled,Is.True);
        yield return new WaitForSeconds(.2f);Assert.That(bullet.is_Die,Is.False);
    }

    [UnityTest]
    public IEnumerator OriginalFXLifecycleUsesScaledTimeAndNativeThrottleKeepsLimits()
    {
        yield return Load();var manager=Polling_manager.instance;
        var go=manager.Object_Polling(1);var fx=go.GetComponent<Bullet_FX>();var lifetime=go.GetComponent<global::Destroy>();
        Assert.That(lifetime,Is.Not.Null);Assert.That(lifetime.Destroy_Time,Is.GreaterThan(0));
        fx.Spawn(0,new Vector3(400,0,400));Assert.That(fx.particle.isPlaying,Is.True);
        Time.timeScale=0;
        try {yield return new WaitForSecondsRealtime(lifetime.Destroy_Time+.1f);Assert.That(go.activeSelf,Is.True,"Original WaitForSeconds pauses with scaled time");}
        finally {Time.timeScale=1;}
        yield return new WaitForSeconds(lifetime.Destroy_Time+.1f);Assert.That(go.activeSelf,Is.False);
        Assert.That(FXThrottle.CanSpawn(64,new Vector3(100,0,100)),Is.True);
        Assert.That(FXThrottle.CanSpawn(63,new Vector3(100,0,100)),Is.True);
        Assert.That(FXThrottle.CanSpawn(62,new Vector3(100,0,100)),Is.True);
        Assert.That(FXThrottle.CanSpawn(61,new Vector3(100,0,100)),Is.False,"Max three in one frame");
        yield return null;
        Assert.That(FXThrottle.CanSpawn(64,new Vector3(100,0,100)),Is.False,"Same gun and nearby position within .05 seconds");
        Assert.That(FXThrottle.CanSpawn(64,new Vector3(101.5f,0,100)),Is.True,"Exact 2.25 distance-squared boundary accepted");
        yield return new WaitForSeconds(.06f);
        Assert.That(FXThrottle.CanSpawn(64,new Vector3(101.5f,0,100)),Is.True);
    }
}

using System;
using System.Collections;
using System.IO;
using System.Collections.Generic;
using System.Linq;
using CatGunner.Runtime;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using TMPro;

public sealed class MissionTextTests
{
    string folder;GameClient client;bool background;
    Transform CanvasRoot=>client.Slider.GetComponentInParent<Canvas>().transform;
    string Report(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports/"+name));
    void Configure(Scene scene,LoadSceneMode mode)
    {if(scene.name=="GameClient")scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<GameClient>(true)).Single().SaveFolderOverride=folder;}
    [UnitySetUp] public IEnumerator Setup()
    {
        background=Application.runInBackground;Application.runInBackground=true;
        folder=Path.Combine(Application.temporaryCachePath,"MissionText-"+Guid.NewGuid().ToString("N"));
        SceneManager.sceneLoaded+=Configure;yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();
        client=GameClient.Instance;client.DailyLogin.Close();client.Tutorial.SetCleared();ForestRuntimeAcceptance.IsGaming=false;
        client.MissionUI.NewSeason_Start();client.MissionUI.Panel_Open();yield return new WaitForSecondsRealtime(.4f);
    }
    [UnityTearDown] public IEnumerator Cleanup()
    {Time.timeScale=1;yield return SceneManager.LoadSceneAsync("TargetPreview");SceneManager.sceneLoaded-=Configure;Application.runInBackground=background;if(Directory.Exists(folder))Directory.Delete(folder,true);}
    [UnityTest] public IEnumerator NormalStartupShowsOriginalTaskNameAndTarget()
    {
        Assert.That(Application.systemLanguage,Is.EqualTo(SystemLanguage.ChineseSimplified),"This GPU baseline uses the current Chinese Editor locale");
        string[] names={"破坏树木","通关关卡","转生","游玩矿山"};
        string[] explanations={"破坏{0}棵树！","通关关卡{0}次！","转生{0}次！","游玩矿山{0}次！"};
        foreach(var row in client.MissionUI.Mission_Item_UI_List)
        {
            var info=client.Missions.Catalogue.Missions[row.Mission_Index];
            Assert.That(row.Name_txt.text,Is.EqualTo(names[info.type]),"original localized task name");
            Assert.That(row.Explain_txt.text,Is.EqualTo(string.Format(explanations[info.type],info.MissionValue)));
            Assert.That(row.Exp_txt.text,Is.EqualTo(info.ExpValue.ToString()),"XP is a separate original image");
        }
        yield return null;
    }
    IEnumerator Capture(string name)
    {yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Report("visual/mission-text-"+name+"-gpu.png"));yield return new WaitForSecondsRealtime(.2f);}
    void AssertChineseVisible(Transform root)
    {
        foreach(var text in root.GetComponentsInChildren<TMP_Text>(true).Where(t=>t.gameObject.activeInHierarchy&&t.text.Any(c=>c>127)))
        {
            text.ForceMeshUpdate();foreach(char ch in text.text.Where(ch=>!char.IsWhiteSpace(ch)))Assert.That(text.font.HasCharacter(ch,true,true),Is.True,"glyph "+ch);
            Assert.That(text.isTextOverflowing,Is.False,text.name+": "+text.text);
        }
    }
    [UnityTest] public IEnumerator StaticTermsAndAllTaskLocalesKeepNumbersAndOriginalRects()
    {
        var data=MissionText.Load();int locale=Array.IndexOf(data.LocaleCodes,WeaponText.LocaleCode(Application.systemLanguage));
        Assert.That(data.Rows.Select(row=>data.Resolve(CanvasRoot,row)).Distinct().Count(),Is.EqualTo(96),"duplicate sibling names must retain distinct label bindings");
        foreach(var row in data.Rows)Assert.That(data.Resolve(CanvasRoot,row).text,Is.EqualTo(row.Values[locale]),row.Key);
        var rowUI=client.MissionUI.Mission_Item_UI_List[0];var rect=rowUI.Explain_txt.rectTransform;var size=rect.sizeDelta;var anchor=rect.anchoredPosition;
        var numbers=client.MissionUI.Mission_Item_UI_List.Select(r=>r.Value_txt.text).ToArray();var money=client.State.Money.ToString();int dia=client.State.Dia;
        // Check the shipped fourteen-language data separately from Editor system selection.
        foreach(var term in data.Tasks)foreach(var value in term.Values)
        {if(term.Description)Assert.That(string.Format(value,123),Does.Contain("123").And.Not.Contain("{0}"));else Assert.That(value,Is.Not.Empty);}
        rowUI.ReloadText(SystemLanguage.English);var font=rowUI.Name_txt.font;var material=rowUI.Name_txt.fontSharedMaterial;
        rowUI.ReloadText(SystemLanguage.ChineseSimplified);var chineseMaterial=rowUI.Name_txt.fontSharedMaterial;
        rowUI.ReloadText(SystemLanguage.ChineseTraditional);Assert.That(rowUI.Name_txt.fontSharedMaterial,Is.SameAs(chineseMaterial));
        rowUI.ReloadText(SystemLanguage.English);rowUI.ReloadText(SystemLanguage.Unknown);
        Assert.That(rowUI.Name_txt.font,Is.SameAs(font));Assert.That(rowUI.Name_txt.fontSharedMaterial,Is.SameAs(material));
        rowUI.ReloadText(SystemLanguage.ChineseSimplified);Assert.That(rect.sizeDelta,Is.EqualTo(size));Assert.That(rect.anchoredPosition,Is.EqualTo(anchor));
        Assert.That(client.MissionUI.Mission_Item_UI_List.Select(r=>r.Value_txt.text),Is.EqualTo(numbers));Assert.That(client.State.Dia,Is.EqualTo(dia));Assert.That(client.State.Money.ToString(),Is.EqualTo(money));
        yield return null;Assert.That(chineseMaterial==null,Is.True);AssertChineseVisible(client.MissionUI.Mission_UI_Panel.transform);yield return Capture("daily");
    }
    IEnumerator Click(Button target)
    {
        Canvas.ForceUpdateCanvases();var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;
        try
        {
            var rect=(RectTransform)target.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));
            var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=mouse.Position},hits);
            Assert.That(hits.FirstOrDefault().gameObject?.GetComponentInParent<Button>(),Is.SameAs(target));
            mouse.Down=true;mouse.Held=true;yield return null;mouse.Down=false;mouse.Held=false;mouse.Up=true;yield return null;mouse.Up=false;yield return null;
        }
        finally{module.inputOverride=null;UnityEngine.Object.Destroy(mouse);}
    }
    [UnityTest] public IEnumerator LocalizedClaimUpdatesBothBarsExactlyOnceAndSurvivesReload()
    {
        var m=client.MissionUI;int index=Array.FindIndex(client.Missions.Catalogue.Missions,x=>!x.is_VIP_Mission&&x.type==0);
        var info=client.Missions.Catalogue.Missions[index];client.State.Mission_TreeCount_Value=info.MissionValue;m.UI_Reload();yield return null;
        var row=m.Mission_Item_UI_List[index];var button=row.GetAble_obj.GetComponentsInChildren<Button>(true).Single();
        Assert.That(button.GetComponentInChildren<TMP_Text>().text,Is.EqualTo("领取"));
        int dia=client.State.Dia;yield return Click(button);Assert.That(client.State.Mission_ExpGet[index],Is.True);
        Assert.That(client.State.Mission_Reward_Exp,Is.EqualTo(info.ExpValue));
        Assert.That(m.Mission_Reward_Slot_List[0].Fill.fillAmount,Is.EqualTo(info.ExpValue/100f));
        Assert.That(m.Exp_Slider.Fill.fillAmount,Is.EqualTo(info.ExpValue/100f));
        row.Reward_Get();Assert.That(client.State.Mission_Reward_Exp,Is.EqualTo(info.ExpValue));Assert.That(client.State.Dia,Is.EqualTo(dia));
        yield return new WaitForSecondsRealtime(.4f);AssertChineseVisible(m.Mission_UI_Panel.transform);yield return Capture("claimed");
        m.Panel_Close();m.Panel_Open();yield return null;Assert.That(row.Name_txt.text,Is.EqualTo("破坏树木"));
        yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();client=GameClient.Instance;
        client.DailyLogin.Close();client.Tutorial.SetCleared();ForestRuntimeAcceptance.IsGaming=false;client.MissionUI.Panel_Open();yield return null;
        Assert.That(client.State.Mission_ExpGet[index],Is.True);Assert.That(client.State.Mission_Reward_Exp,Is.EqualTo(info.ExpValue));
        Assert.That(client.MissionUI.Mission_Item_UI_List[index].Explain_txt.text,Is.EqualTo("破坏"+info.MissionValue+"棵树！"));Assert.That(client.State.Dia,Is.EqualTo(dia));
    }
    [UnityTest] public IEnumerator PassAndSeasonPanelsKeepOriginalTextAndPurchasesUntouched()
    {
        var m=client.MissionUI;int dia=client.State.Dia;bool vip=client.State.Mission_is_Vip,luxury=client.State.Mission_is_Luxury;
        foreach(var pair in new[]{(m.Vip_Purchase_Panel_obj,"passes"),(m.NewSeason_Panel_obj,"season")})
        {
            pair.Item1.SetActive(true);yield return new WaitForSecondsRealtime(.4f);AssertChineseVisible(pair.Item1.transform);yield return Capture(pair.Item2);pair.Item1.SetActive(false);
        }
        Assert.That(client.State.Dia,Is.EqualTo(dia));Assert.That(client.State.Mission_is_Vip,Is.EqualTo(vip));Assert.That(client.State.Mission_is_Luxury,Is.EqualTo(luxury));
        Assert.That(MissionText.Load().TaskName(-1,SystemLanguage.English),Is.Null);Assert.That(MissionText.Load().TaskExplanation(4,1,SystemLanguage.English),Is.Null);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using CatGunner.Runtime;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEngine.UI;

public sealed class MissionSortingTests
{
    string folder; GameClient client; bool background;
    void Configure(Scene s,LoadSceneMode mode){if(s.name=="GameClient")s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<GameClient>(true)).Single().SaveFolderOverride=folder;}
    [UnitySetUp] public IEnumerator Setup(){background=Application.runInBackground;Application.runInBackground=true;Time.timeScale=1;folder=Path.Combine(Application.temporaryCachePath,"MissionSorting-"+Guid.NewGuid().ToString("N"));SceneManager.sceneLoaded+=Configure;yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();client=GameClient.Instance;ForestRuntimeAcceptance.IsGaming=false;client.MissionUI.NewSeason_Start();client.MissionUI.Panel_Open();yield return null;yield return null;}
    [UnityTearDown] public IEnumerator Cleanup(){Time.timeScale=1;if(EventSystem.current!=null){var module=EventSystem.current.GetComponent<StandaloneInputModule>();if(module!=null)module.inputOverride=null;}yield return SceneManager.LoadSceneAsync("TargetPreview");SceneManager.sceneLoaded-=Configure;if(Directory.Exists(folder))Directory.Delete(folder,true);Application.runInBackground=background;}
    int[] Order()=>client.MissionUI.Mission_Item_UI_List.OrderBy(r=>r.transform.GetSiblingIndex()).Select(r=>r.Mission_Index).ToArray();
    int ModelCall(string name,int index){var method=typeof(Missions).GetMethod(name);Assert.That(method,Is.Not.Null,name);return (int)method.Invoke(client.Missions,new object[]{index});}
    void Counters(int tree,int stage,int rebirth,int mine){client.State.Mission_TreeCount_Value=tree;client.State.Mission_StageClear_Value=stage;client.State.Mission_Rebirth_Value=rebirth;client.State.Mission_PlayMine_Value=mine;client.MissionUI.UI_Reload();}
    static readonly int[] Mixed={0,6,12,18,1,2,3,4,5,20,21,7,8,9,10,11,22,13,14,15,16,17,19};
    void Capture(string suffix){ScreenCapture.CaptureScreenshot(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports/visual/mission-sorting-"+suffix+"-gpu.png")));}
    static Button ClaimButton(Mission_Item_UI row)=>row.GetComponentsInChildren<Button>(true).Single(b=>Enumerable.Range(0,b.onClick.GetPersistentEventCount()).Any(i=>b.onClick.GetPersistentTarget(i)==row&&b.onClick.GetPersistentMethodName(i)=="Reward_Get"));
    static IEnumerator Click(Button b)
    {
        Canvas.ForceUpdateCanvases();var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;
        var rt=(RectTransform)b.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,rt.TransformPoint(rt.rect.center));var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=mouse.Position},hits);
        Assert.That(hits.Count,Is.GreaterThan(0));Assert.That(hits[0].gameObject.GetComponentInParent<Button>(),Is.SameAs(b),"Sorted row must own top raycast");
        yield return null;mouse.Down=true;mouse.Held=true;yield return null;mouse.Down=false;mouse.Held=false;mouse.Up=true;yield return null;mouse.Up=false;yield return null;module.inputOverride=null;UnityEngine.Object.Destroy(mouse);
    }
    [UnityTest] public IEnumerator MixedCountersSortReadyRowsByTypeThenOriginalIndexWithoutRebinding()
    {
        var m=client.MissionUI;var identities=m.Mission_Item_UI_List.Select(r=>r.GetInstanceID()).ToArray();Counters(100,5,1,1);yield return null;yield return null;
        Assert.That(Order(),Is.EqualTo(Mixed));for(int n=0;n<4;n++){m.UI_Reload();yield return null;Assert.That(Order(),Is.EqualTo(Mixed));}
        Assert.That(m.Mission_Item_UI_List.Select(r=>r.GetInstanceID()),Is.EqualTo(identities));Assert.That(m.Mission_Item_UI_List.Select(r=>r.Mission_Index),Is.EqualTo(Enumerable.Range(0,23)));Capture("ready-order");yield return null;
    }
    [UnityTest] public IEnumerator LuxuryAndVipPrioritiesKeepOriginalEligibilityButCannotGrantPaidRewards()
    {
        Counters(int.MaxValue,int.MaxValue,int.MaxValue,int.MaxValue);var s=client.State;var m=client.MissionUI;s.Mission_ExpGet[0]=true;m.UI_Reload();yield return null;
        Assert.That(Order(),Is.EqualTo(Enumerable.Range(1,19).Concat(new[]{0,20,21,22})));Assert.That(ModelCall("MissionStatus",0),Is.EqualTo(3));Assert.That(ModelCall("MissionSortPriority",0),Is.EqualTo(1));Assert.That(ModelCall("MissionSortPriority",20),Is.EqualTo(1));
        s.Mission_is_Luxury=true;m.UI_Reload();yield return null;Assert.That(Order()[0],Is.Zero);Assert.That(ModelCall("MissionSortPriority",0),Is.Zero);
        s.Mission_ExpGet[1]=s.Mission_ExpGet_Luxury[1]=true;s.Mission_is_Vip=true;m.UI_Reload();yield return null;
        Assert.That(Order(),Is.EqualTo(new[]{0,2,3,4,5,20,21,6,7,8,9,10,11,22,12,13,14,15,16,17,18,19,1}));Assert.That(ModelCall("MissionSortPriority",1),Is.EqualTo(2));
        int xp=s.Mission_Reward_Exp,level=s.Mission_Reward_Lv,dia=s.Dia;m.Mission_Item_UI_List[20].Reward_Get();m.Mission_Item_UI_List[0].Reward_Get_Luxury();Assert.That(s.Mission_Reward_Exp,Is.EqualTo(xp));Assert.That(s.Mission_Reward_Lv,Is.EqualTo(level));Assert.That(s.Dia,Is.EqualTo(dia));Assert.That(s.Mission_ExpGet[20],Is.False);Assert.That(s.Mission_ExpGet_Luxury[0],Is.False);
    }
    [UnityTest] public IEnumerator SortedOriginalButtonsClaimTheirOwnTaskExactlyOnceAndPersist()
    {
        Counters(0,0,1,1);yield return null;yield return null;Assert.That(Order().Take(2),Is.EqualTo(new[]{12,18}));int xp=client.State.Mission_Reward_Exp,dia=client.State.Dia;
