            Assert.That(cat.TryFireShotgun(Vector3.one*1000,Vector3.forward,cat.Damage,cat.Damage_str,false),Is.False);
            Assert.That(Random.value,Is.EqualTo(first),"Pool failure occurs before angle sampling");
