            Assert.That(cat.Shoot_particle.isPlaying,Is.True);Assert.That(Spread(cat),Is.Zero);
        }
        finally {bridge.enabled=false;ForestDamageDispatch.DamageTextPending-=listener;Random.state=originalRandom;}
