        Assert.That(background.gameObject.activeSelf,Is.False);
        Assert.That(joystick.Direction,Is.EqualTo(Vector2.zero));
        Assert.That(handle.anchoredPosition,Is.EqualTo(Vector2.zero));
    }
}

