        {
            var text=Data.Resolve(CanvasRoot,row);if(!text.transform.IsChildOf(root)||!text.gameObject.activeInHierarchy)continue;
            text.ForceMeshUpdate();Assert.That(text.isTextOverflowing,Is.False,row.Path);
