    }
    public void Tree_Destroyed()
    {
        if(!ForestRuntimeAcceptance.IsGaming) return;
        TreeCount_Now--;
        TreeDestroyed?.Invoke();
        if(TreeCount_Now<1) WaveCleared?.Invoke();
    }
}

