    [UnityEngine.Scripting.APIUpdating.MovedFrom(true, sourceNamespace: "CatGunner.Recovery", sourceAssembly: "CatGunner.Recovery", sourceClassName: "RecoveryTargetRotation")] public sealed class TargetRotation : MonoBehaviour
    {
        [Serializable] public sealed class Configuration
        {
            public int SourceComponent;
            public float Duration;
            public Vector3 EndEuler,SourcePosition,SourceScale;
            public Quaternion SourceQuaternion;
        }
        Configuration config;
