    // Ordinary DiaPig arithmetic from vc257. This is a counter, never a purchase
    // provider. Trusted wall-clock catch-up/RecordGain are deliberately absent.
    [UnityEngine.Scripting.APIUpdating.MovedFrom(true, sourceNamespace: "CatGunner.Recovery", sourceAssembly: "CatGunner.Recovery", sourceClassName: "OriginalDiaPigCounter")] public sealed class DiaPigCounter
    {
        public readonly int Maximum;
