                float2 p=(uv-eye.xy)/max(eye.zw,float2(.001,.001));
                if (abs(p.x)>1.25 || abs(p.y)>1.15) return col;
                fixed4 cheek=tex2D(_SkinTex,eye.xy+float2(-eye.z*1.35,0));
                fixed4 other=tex2D(_SkinTex,eye.xy+float2(eye.z*1.35,0));
