// Port of vc257 Custom/DiamondClipSprite GLES3 operations/pass state.
// Untiled UV radius .5 discards corners; tiled UV samples _MainTex * _Color.
// The original shader does not multiply the SpriteRenderer's vertex tint.
Shader "Game/MineGroundCompatibility"
{
    Properties { [PerRendererData] _MainTex("Original floor texture",2D)="white"{} _Color("Original tint",Color)=(1,1,1,1) }
    SubShader
    {
        Tags {"Queue"="Transparent" "RenderType"="Transparent" "CanUseSpriteAtlas"="True"}
        Cull Off ZWrite Off ZTest LEqual Blend SrcAlpha OneMinusSrcAlpha
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"
            sampler2D _MainTex;float4 _MainTex_ST;fixed4 _Color;
            struct Input {float4 position:POSITION;float2 uv:TEXCOORD0;};
            struct Output {float4 position:SV_POSITION;float2 tiled:TEXCOORD0;float2 uv:TEXCOORD1;};
            Output vert(Input input){Output o;o.position=UnityObjectToClipPos(input.position);o.tiled=TRANSFORM_TEX(input.uv,_MainTex);o.uv=input.uv;return o;}
            fixed4 frag(Output input):SV_Target {float2 offset=input.uv-float2(.5,.5);clip(.25-dot(offset,offset));return tex2D(_MainTex,input.tiled)*_Color;}
            ENDCG
        }
    }
}

// Evidence-constrained BIRP compatibility shader, not decompiled original source.
// Original native contract sends fill amount through SpriteRenderer.color.r.
Shader "Game/ForestHealthFill"
{
    Properties
    {
        [PerRendererData] _MainTex("Original sprite",2D)="white"{}
        [HideInInspector] _RendererColor("Renderer color",Color)=(1,1,1,1)
        _FillMinX("Minimum original sprite X",Float)=-0.5
        _FillMaxX("Maximum original sprite X",Float)=0.5
    }
    SubShader
    {
        Tags {"Queue"="Transparent" "RenderType"="Transparent" "CanUseSpriteAtlas"="True" "DisableBatching"="True"}
        Cull Off ZWrite Off Lighting Off
        Blend One OneMinusSrcAlpha
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"
            fixed4 _RendererColor;
            struct appdata {float4 vertex:POSITION;float2 uv:TEXCOORD0;fixed4 color:COLOR;};
            struct v2f {float4 vertex:SV_POSITION;float2 uv:TEXCOORD0;float x:TEXCOORD1;fixed4 color:COLOR;};
            sampler2D _MainTex;
            float _FillMinX,_FillMaxX;
            v2f vert(appdata v)
            {
                v2f o;o.vertex=UnityObjectToClipPos(v.vertex);o.uv=v.uv;
                o.x=(v.vertex.x-_FillMinX)/max(_FillMaxX-_FillMinX,0.00001);o.color=v.color*_RendererColor;
                return o;
            }
            fixed4 frag(v2f i):SV_Target
            {
                clip(i.color.r-i.x);
                fixed4 c=tex2D(_MainTex,i.uv);c.a*=i.color.a;c.rgb*=c.a;
                return c;
            }
            ENDCG
        }
    }
}

Shader "Game/VerticalIceCliff"
{
    Properties { _MainTex("Vertical ice face",2D)="white"{} }
    SubShader
    {
        Tags {"Queue"="Transparent" "RenderType"="Transparent"}
        Cull Back ZWrite Off ZTest LEqual Blend SrcAlpha OneMinusSrcAlpha
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"
            sampler2D _MainTex;
            struct Input {float4 position:POSITION;float3 normal:NORMAL;float2 uv:TEXCOORD0;};
            struct Output {float4 position:SV_POSITION;float2 uv:TEXCOORD0;float3 normal:TEXCOORD1;};
            Output vert(Input i){Output o;o.position=UnityObjectToClipPos(i.position);o.uv=i.uv;o.normal=UnityObjectToWorldNormal(i.normal);return o;}
            fixed4 frag(Output i):SV_Target
            {
                fixed4 ice=tex2D(_MainTex,i.uv);
